"""Writes tests/conservation_bulk_tests.move: 10 000 AC21 sequences."""
from pathlib import Path

out = ["/// AC21 release gate: 10 000 random op sequences (see conservation_tests).",
       "/// Generated by scripts/gen_bulk_tests.py; do not edit by hand.",
       "#[test_only]", "module whiteout::conservation_bulk_tests;", "",
       "use whiteout::conservation_tests::run_many;", ""]
for i in range(1000):
    out.append(f"#[test]\nfun bulk_{i:04d}() {{ run_many({2_000_003 + i * 10 * 7919}, 10) }}\n")
Path(__file__).resolve().parent.parent.joinpath("tests/conservation_bulk_tests.move").write_text("\n".join(out))
